        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_cube(n):
    if n < 0:
        return False
    # Estimate the cube root
    root_float = n**(1/3)
    # Check integers around the float approximation
    # We check floor(root) and ceil(root) to handle floating point inaccuracies
    r1 = int(math.floor(root_float))
    r2 = r1 + 1

    if r1**3 == n:
        return r1
    if r2**3 == n:
