import math

def is_perfect_cube(n):
    if n < 0:
        return False
    if n == 0:
        return True
    # Estimate the cube root
    root = round(n**(1/3))
    return root**3 == n

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Task 1: Verify q = 19
q_verify = 19
N_verify = q_verify**2 - q_verify + 1
is_cube = is_perfect_cube(N_verify)
if is_cube:
    p_verify = round(N_verify**(1/3))
    print(f"Verification for q={q_verify}:")
    print(f"N = {N_verify}")
    print(f"Is a perfect cube: {is_cube}")
    print(f"Candidate p = {p_verify}")
    print(f"Is p prime: {is_prime(p_verify)}")
    print(f"p != q: {p_verify != q_verify}")
else:
    print(f"Verification for q={q_verify}: N={N_verify} is not a perfect cube.")


# Task 2: Check primes q < 19 such that q != 2 mod 3
primes_to_check = [q for q in range(2, 19) if is_prime(q)]
print("\n--- Checking q < 19 (q not congruent to 2 mod 3) ---")
solutions_small_q = []

for q in primes_to_check:
    if q % 3 == 2:
        print(f"Skipping q={q} (q = 2 mod 3)")
        continue

    N = q**2 - q + 1
    is_cube = is_perfect_cube(N)

    if is_cube:
        p = round(N**(1/3))
        if is_prime(p) and p != q:
            solutions_small_q.append(q)
            print(f"Solution found for q={q} with p={p}")
        else:
            print(f"q={q} yields N={N} = {p}^3, but p is not a prime or p=q.")
    else:
        print(f"q={q}: N={N} is not a perfect cube.")

print("\nSummary of small q search:", solutions_small_q)
